use crate::frame::{self, Frame};
use crate::value;
use bstr::{BStr, BString};
use shirabe_php_shim::{ToPhpString, bformat, exit, os_str_from_bytes, path_from_bytes, php_str};
use shirabe_symfony_process::PhpExecutableFinder;

const GLUE_SCRIPT: &[u8] = include_bytes!("../php/worker.php");

/// Proxy stub classes made autoloadable inside the worker, generated by
/// `scripts/plugin-stub-generator/generate-stubs` into `php/stubs/`. `build.rs` builds the list
/// from the directory itself.
const STUB_FILES: &[(&BStr, &[u8])] = include!(concat!(env!("OUT_DIR"), "/stub-files.rs"));

/// Hand-written worker-side classes under `php/runtime/` (two-world implementations with behavior
/// of their own, not mechanical proxies), written into the same autoload directory as the
/// generated stubs so the prepended stub autoloader resolves their FQCNs ahead of any real class
/// file. `build.rs` builds the list from the directory itself.
const RUNTIME_FILES: &[(&BStr, &[u8])] = include!(concat!(env!("OUT_DIR"), "/runtime-files.rs"));

/// Guard classes made autoloadable inside the worker, behind the stubs: they shadow the real
/// Composer class of every Rust-owned FQCN no stub proxies, so the worker cannot fall through to
/// the real implementation and run an instance the Rust side never sees. Generated by
/// `scripts/plugin-stub-generator/generate-stubs` into `php/guards/`. `build.rs` builds the list
/// from the directory itself.
const GUARD_FILES: &[(&BStr, &[u8])] = include!(concat!(env!("OUT_DIR"), "/guard-files.rs"));

struct Worker {
    stream: std::os::unix::net::UnixStream,
    // Also queried for its exit status when a socket read/write fails, to tell a dead worker
    // apart from a framing bug.
    child: std::process::Child,
    // Holds the glue script and class files the worker loads; removed once the worker has ended.
    // The worker lives in a never-dropped static, so it is not removed otherwise.
    tempdir: Option<tempfile::TempDir>,
}

impl Worker {
    /// Describes the PHP worker's current process state, to be attached as `anyhow::Context` to
    /// an I/O error so a dead worker (crash, OOM kill, ...) can be told apart from a live one
    /// hitting a framing bug.
    #[expect(
        clippy::disallowed_types,
        clippy::disallowed_macros,
        reason = "an anyhow context the port raises about its child, holding no PHP string"
    )]
    fn worker_state(&mut self) -> String {
        match self.child.try_wait() {
            Ok(Some(status)) => format!("PHP worker process already exited: {status}"),
            Ok(None) => format!(
                "PHP worker process (pid {}) is still running",
                self.child.id()
            ),
            Err(wait_err) => format!("failed to check PHP worker process status: {wait_err}"),
        }
    }

    /// The status the worker ended with, waiting a moment for it to be reaped, or `None` while it
    /// is still running.
    fn exit_status(&mut self) -> Option<std::process::ExitStatus> {
        // The socket closes as the worker ends, a moment before it can be reaped.
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(1);
        loop {
            match self.child.try_wait() {
                Ok(Some(status)) => return Some(status),
                Ok(None) if std::time::Instant::now() < deadline => {
                    std::thread::sleep(std::time::Duration::from_millis(10));
                }
                _ => return None,
            }
        }
    }

    /// Runs `f` on the worker's socket. A failure of the worker having ended comes back as its exit
    /// status, with the temp dir removed, as nothing reads it any more; any other failure comes
    /// back as the I/O error with the worker's state attached.
    fn on_stream<T>(
        &mut self,
        f: impl FnOnce(&mut std::os::unix::net::UnixStream) -> std::io::Result<T>,
    ) -> anyhow::Result<Result<T, std::process::ExitStatus>> {
        match f(&mut self.stream) {
            Ok(value) => Ok(Ok(value)),
            Err(e) => match self.exit_status() {
                Some(status) => {
                    self.tempdir = None;
                    Ok(Err(status))
                }
                None => Err(anyhow::Error::new(e).context(self.worker_state())),
            },
        }
    }
}

/// What the embedder adds to the worker's command line on top of what the protocol itself needs.
#[derive(Debug, Clone, Default)]
pub struct WorkerConfig {
    /// `-d name=value` settings, in order.
    pub ini_settings: Vec<(BString, BString)>,
    /// Environment variables set in the worker's environment.
    pub env: Vec<(std::ffi::OsString, std::ffi::OsString)>,
    /// PHP class files written into the autoload directory of `php/runtime/`, keyed by their path
    /// relative to it (`Shirabe/Foo.php` for `Shirabe\Foo`), so they resolve the same way.
    pub runtime_files: &'static [(&'static BStr, &'static [u8])],
    /// The classes, among `runtime_files`, whose static `table()` adds named entry points to the
    /// worker's dispatch table beside the protocol's own. A name may be defined only once.
    pub entry_point_classes: Vec<BString>,
}

/// Builds the [`WorkerConfig`] a worker is spawned with.
static WORKER_CONFIG_PROVIDER: std::sync::OnceLock<fn() -> WorkerConfig> =
    std::sync::OnceLock::new();

/// Registers the function that builds the [`WorkerConfig`] the worker is spawned with. It is asked
/// at spawn time, so a setting that depends on the environment sees the environment of that
/// moment. It must be registered before anything spawns the worker; an embedder that adds nothing
/// registers `WorkerConfig::default`. A second registration is ignored.
pub fn set_worker_config_provider(provider: fn() -> WorkerConfig) {
    let _ = WORKER_CONFIG_PROVIDER.set(provider);
}

fn worker_config() -> WorkerConfig {
    let provider = WORKER_CONFIG_PROVIDER.get().unwrap_or_else(|| {
        panic!(
            "PHP RPC: the worker is spawned before set_worker_config_provider is called; it would \
             lack the embedder's settings and entry points for the rest of the process"
        )
    });
    provider()
}

/// The PHP worker, spawned on first use.
static WORKER: std::sync::Mutex<Option<Worker>> = std::sync::Mutex::new(None);

/// Whether the PHP worker process has been spawned by this process. Callers that only need to
/// mirror state into an already-running worker (e.g. `InstalledVersions::reload` pushes) use
/// this to avoid spawning a worker that would have nothing to observe.
pub fn worker_is_running() -> bool {
    WORKER
        .lock()
        .unwrap_or_else(|e| panic!("PHP RPC: worker mutex poisoned: {e}"))
        .is_some()
}

/// Runs `f` on the worker while holding its mutex, spawning the worker first if it is not running.
fn with_worker<T>(f: impl FnOnce(&mut Worker) -> T) -> anyhow::Result<T> {
    let mut guard = WORKER
        .lock()
        .unwrap_or_else(|e| panic!("PHP RPC: worker mutex poisoned: {e}"));
    let worker = match &mut *guard {
        Some(worker) => worker,
        None => guard.insert(
            spawn_worker(&worker_config())
                .map_err(|e| anyhow::anyhow!("failed to spawn the PHP worker: {e:#}"))?,
        ),
    };
    Ok(f(worker))
}

/// Writes one frame while holding the worker mutex only for the duration of the write, so the
/// session owner (see `session`) can interleave sends and blocking reads without keeping the worker
/// locked across a whole call. A `ReleaseHandle` for every PHP entity handle dropped since the
/// previous write goes out first.
pub(crate) fn send_frame(frame: &Frame) -> anyhow::Result<()> {
    with_worker_stream(|stream| {
        for entity_id in value::take_released_php_entity_ids() {
            frame::write_frame(stream, &Frame::ReleaseHandle { entity_id })?;
        }
        frame::write_frame(stream, frame)
    })
}

pub(crate) fn recv_frame() -> anyhow::Result<Frame> {
    with_worker_stream(frame::read_frame)
}

/// Runs `f` on the worker's socket. If it fails because the worker has ended, ends this process the
/// same way: the worker stands in for the PHP process Composer runs in, so a plugin's `exit()`, a
/// fatal error or a signal that ends the worker ends Shirabe with the same exit code or signal, as
/// it ends Composer. The end unwinds like PHP's `exit` (see [`exit`]), so the stack is
/// dropped on the way out; a failure met while the stack is already unwinding is returned as an
/// error instead, since unwinding again would abort.
///
/// TODO(php-runtime): Composer's own shutdown functions, such as the memory-limit hint its
/// Application registers, run in the process that ended and so are not run here.
fn with_worker_stream<T>(
    f: impl FnOnce(&mut std::os::unix::net::UnixStream) -> std::io::Result<T>,
) -> anyhow::Result<T> {
    let status = match with_worker(|worker| worker.on_stream(f))?? {
        Ok(value) => return Ok(value),
        Err(status) => status,
    };
    if std::thread::panicking() {
        anyhow::bail!("PHP worker process already exited: {status}");
    }
    exit(status)
}

/// The descriptor the worker's end of the RPC socket is installed on in the child. `pre_exec`
/// dup2s onto it, which closes whatever the fork inherited there, so the number is ours to pick
/// as long as it is above the three standard streams.
const WORKER_SOCKET_FD: std::os::fd::RawFd = 3;

fn spawn_worker(config: &WorkerConfig) -> anyhow::Result<Worker> {
    let php = PhpExecutableFinder::new()
        .find(false)
        .ok_or_else(|| anyhow::anyhow!("no PHP executable found"))?;

    let tempdir = tempfile::tempdir()?;
    let script_path = tempdir.path().join("worker.php");
    std::fs::write(&script_path, GLUE_SCRIPT)?;

    let stubs_dir = tempdir.path().join("stubs");
    let guards_dir = tempdir.path().join("guards");
    let files = STUB_FILES
        .iter()
        .chain(RUNTIME_FILES)
        .chain(config.runtime_files)
        .map(|entry| (&stubs_dir, entry))
        .chain(GUARD_FILES.iter().map(|entry| (&guards_dir, entry)));
    for (dir, (relative_path, contents)) in files {
        let path = dir.join(path_from_bytes(relative_path));
        std::fs::create_dir_all(path.parent().expect("generated class paths have a parent"))?;
        std::fs::write(&path, contents)?;
    }

    // A connected pair, not a bound path: an AF_UNIX path has to fit in `sun_path` (108 bytes),
    // which a long TMPDIR overruns, and the worker is a child we spawn ourselves, so it can
    // inherit its end instead of connecting to one. The pair is connected from the start, so
    // there is no accept to wait for either — a child that dies before reading shows up as EOF
    // on the first call, with its exit status attached by `worker_state`.
    let (stream, child_end) = std::os::unix::net::UnixStream::pair()?;
    let child_end = std::os::fd::OwnedFd::from(child_end);

    let mut command = std::process::Command::new(path_from_bytes(&php));
    command
        // The Rust-side codec produces the byte representation of the default (and only
        // supported) serialize_precision; pin the child to it in case a distro php.ini overrides
        // the default.
        .arg("-d")
        .arg("serialize_precision=-1")
        // The Composer runtime bundle has no phar signature.
        .arg("-d")
        .arg("phar.require_hash=0");
    for (name, value) in &config.ini_settings {
        command
            .arg("-d")
            .arg(os_str_from_bytes(&bformat!("{name}={value}")));
    }
    command.envs(config.env.iter().map(|(name, value)| (name, value)));
    command
        .arg(&script_path)
        .arg(os_str_from_bytes(&WORKER_SOCKET_FD.to_php_string()))
        .arg(&stubs_dir)
        .arg(&guards_dir)
        .args(config.entry_point_classes.iter().map(os_str_from_bytes));
    // SAFETY: the closure only calls async-signal-safe syscalls, as required between fork and
    // exec. It owns the child end, so the descriptor stays alive until the exec happens.
    unsafe {
        std::os::unix::process::CommandExt::pre_exec(&mut command, move || {
            install_worker_socket_fd(&child_end)
        });
    }
    let child = command.spawn()?;
    // Dropping the command drops the pre_exec closure with it, closing the parent's copy of the
    // child end. Without that the parent would never observe EOF on a dead worker.
    drop(command);

    Ok(Worker {
        stream,
        child,
        tempdir: Some(tempdir),
    })
}

/// For testing only: spawns a worker of its own with `config`, calls the PHP function
/// `function_name` there, and ends the worker again.
pub fn __call_function_in_new_worker(
    config: &WorkerConfig,
    function_name: &BStr,
    args: Vec<value::RpcValue>,
) -> anyhow::Result<value::RpcValue> {
    let mut worker = spawn_worker(config)?;
    let result = (|| {
        frame::write_frame(
            &mut worker.stream,
            &Frame::CallFunction {
                corr_id: 1,
                function_name: function_name.to_owned(),
                args,
            },
        )?;
        match frame::read_frame(&mut worker.stream)? {
            Frame::Return { value, .. } => Ok(value),
            other => Err(anyhow::anyhow!("unexpected reply: {other:?}")),
        }
    })();
    worker.child.kill()?;
    worker.child.wait()?;
    result
}

/// Moves the worker's end of the socket onto [`WORKER_SOCKET_FD`] in the freshly forked child.
fn install_worker_socket_fd(child_end: &std::os::fd::OwnedFd) -> std::io::Result<()> {
    use std::os::fd::{AsRawFd as _, FromRawFd as _, IntoRawFd as _};

    if child_end.as_raw_fd() == WORKER_SOCKET_FD {
        // dup2(fd, fd) is a no-op that leaves FD_CLOEXEC set, which would close the descriptor
        // on exec; clear the flag by hand instead.
        nix::fcntl::fcntl(
            child_end,
            nix::fcntl::FcntlArg::F_SETFD(nix::fcntl::FdFlag::empty()),
        )?;
        return Ok(());
    }
    // SAFETY: dup2_raw closes the target if it is open and makes it a duplicate of the child
    // end; releasing the returned owner keeps it open across the exec.
    let installed = unsafe {
        nix::unistd::dup2_raw(
            child_end,
            std::os::fd::OwnedFd::from_raw_fd(WORKER_SOCKET_FD),
        )?
    };
    let _ = installed.into_raw_fd();
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::value::RpcValue;
    use shirabe_php_shim::Exit;

    #[test]
    fn an_idle_worker_outlasts_the_socket_timeout() {
        let config = WorkerConfig {
            ini_settings: vec![("default_socket_timeout".into(), "1".into())],
            ..WorkerConfig::default()
        };
        let mut worker = spawn_worker(&config).expect("failed to spawn PHP worker");
        std::thread::sleep(std::time::Duration::from_secs(3));

        let reply = worker
            .on_stream(|stream| {
                frame::write_frame(
                    stream,
                    &Frame::CallFunction {
                        corr_id: 1,
                        function_name: "strtoupper".into(),
                        args: vec![RpcValue::string("idle")],
                    },
                )?;
                frame::read_frame(stream)
            })
            .expect("a live worker is not an I/O error")
            .expect("the worker is still running");
        assert!(
            matches!(&reply, Frame::Return { value, .. } if *value == RpcValue::string("IDLE")),
            "unexpected reply: {reply:?}"
        );
        worker.child.kill().expect("failed to kill PHP worker");
        worker.child.wait().expect("failed to reap PHP worker");
    }

    #[test]
    fn request_error_reports_dead_worker_exit_status() {
        let mut worker =
            spawn_worker(&WorkerConfig::default()).expect("failed to spawn PHP worker");
        worker.child.kill().expect("failed to kill PHP worker");
        worker.child.wait().expect("failed to reap PHP worker");

        // Writing may still succeed into the socket buffer; the read is what must fail.
        let _ = frame::write_frame(
            &mut worker.stream,
            &Frame::CallFunction {
                corr_id: 1,
                function_name: "defined".into(),
                args: vec![RpcValue::string("PHP_VERSION")],
            },
        );
        frame::read_frame(&mut worker.stream).expect_err("reading from a dead worker should fail");
        let state = worker.worker_state();
        assert!(
            state.contains("PHP worker process already exited"),
            "unexpected worker state: {state}"
        );
    }

    #[test]
    fn a_dead_worker_comes_back_as_its_exit_status() {
        let mut worker =
            spawn_worker(&WorkerConfig::default()).expect("failed to spawn PHP worker");
        worker.child.kill().expect("failed to kill PHP worker");

        let status = worker
            .on_stream(|stream| {
                // Writing may still succeed into the socket buffer; the read is what must fail.
                let _ = frame::write_frame(
                    stream,
                    &Frame::CallFunction {
                        corr_id: 1,
                        function_name: "defined".into(),
                        args: vec![RpcValue::string("PHP_VERSION")],
                    },
                );
                frame::read_frame(stream)
            })
            .expect("a dead worker is not an I/O error")
            .expect_err("reading from a dead worker should fail");
        assert!(matches!(
            Exit::from(status),
            Exit::Signal(signal) if signal == nix::sys::signal::Signal::SIGKILL as i32
        ));
        assert!(worker.tempdir.is_none());
    }
}
